\begin{defn}
  \ollabel{defn:enumerable}
  A set~$A$ is !!{enumerable} iff either $A = \emptyset$ or there is
  an enumeration of~$A$. We say that $A$ is !!{nonenumerable} iff $A$
  is not !!{enumerable}.
\end{defn}

